MODEL_HELP = {
    "tiny": "Fastest and lightest model, but with lower transcription accuracy.",
    "base": "Lightweight model with slightly better accuracy than Tiny.",
    "small": "Balanced model for speed, memory usage and accuracy.",
    "medium": "Higher transcription quality with increased memory and processing requirements.",
    "large-v2": "High-accuracy Whisper model with high memory and compute requirements.",
    "large-v3": "High-accuracy Whisper model with high memory and compute requirements.",
    "turbo": "Optimized large Whisper model providing high accuracy with significantly faster inference.",
}


def model_help(name):
    """Describe a currently exposed model without adding entries to its catalog."""
    detail = MODEL_HELP.get(name.removesuffix(".en"), "")
    if name.endswith(".en"):
        detail += " English-only model."
    return HELP["model"] + (f"\n\n{name}: {detail}" if detail else "")


def set_help(widget, key):
    """Attach a shared explanation to a widget or menu action without changing state."""
    widget.setToolTip(HELP[key])
